{
  "gateway": "linkedin_native_action",
  "mode": "direct",
  "description": "Complete LinkedIn Marketing API native gateway generated from the local li-lms-2026-05 documentation snapshot: ads, accounts, creatives, audiences, conversions, lead sync, community management, media, events, experiments, analytics, and REST.li batch/action endpoints. Use action=LIST_ACTIONS or DESCRIBE_ACTION for local discovery, including ad-account user access. Writes are dry-run by default.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Generated LinkedIn native action name, LIST_ACTIONS, or DESCRIBE_ACTION. Search adAccountUsers or organizationAcls to discover access-management operations."
      },
      "target_action": {
        "type": "string",
        "description": "Action to inspect when action=DESCRIBE_ACTION."
      },
      "search": {
        "type": "string",
        "description": "With LIST_ACTIONS, filter by action name, resource, or endpoint."
      },
      "category": {
        "type": "string",
        "description": "With LIST_ACTIONS, filter by documentation category."
      },
      "read_only": {
        "type": "boolean",
        "description": "With LIST_ACTIONS, filter read or write operations."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 50,
        "description": "With LIST_ACTIONS, return at most this many actions. Defaults to 50 to stay inside MCP transport limits."
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "default": 0,
        "description": "With LIST_ACTIONS, continue from this zero-based action offset."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional explicit LinkedIn OAuth connection ID for users with multiple LinkedIn accounts."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Path placeholder values. Required values may also be passed top-level."
      },
      "params": {
        "type": "object",
        "additionalProperties": {},
        "description": "LinkedIn REST.li query/finder/action parameters. params and query are always placed in the URL, including for write requests."
      },
      "query": {
        "type": "object",
        "additionalProperties": {},
        "description": "Explicit URL query parameters; overrides duplicate keys from params."
      },
      "payload": {
        "anyOf": [
          {
            "type": "object",
            "additionalProperties": {}
          },
          {
            "type": "array",
            "items": {}
          },
          {
            "type": "string",
            "maxLength": 4194304
          }
        ],
        "description": "JSON request body for POST/PUT/PATCH actions. Accepts an object, a REST.li batch array, or a stringified JSON object/array for cached-client compatibility. Never used as URL query parameters."
      },
      "restli_method": {
        "type": "string",
        "enum": [
          "ACTION",
          "CREATE",
          "BATCH_CREATE",
          "GET",
          "BATCH_GET",
          "FINDER",
          "UPDATE",
          "BATCH_UPDATE",
          "PARTIAL_UPDATE",
          "BATCH_PARTIAL_UPDATE",
          "DELETE",
          "BATCH_DELETE"
        ],
        "description": "Optional X-RestLi-Method override for REST.li create, finder, action, update, partial-update, and batch semantics."
      },
      "http_method_override": {
        "type": "string",
        "enum": [
          "GET",
          "POST",
          "PUT",
          "PATCH",
          "DELETE"
        ],
        "description": "Optional X-HTTP-Method-Override for LinkedIn query tunneling."
      },
      "body_format": {
        "type": "string",
        "enum": [
          "json",
          "form"
        ],
        "description": "Request body encoding. Use form with http_method_override for REST.li query tunneling; defaults to json."
      },
      "api_version": {
        "type": "string",
        "pattern": "^\\d{6}$",
        "description": "Optional Linkedin-Version override in YYYYMM format."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required with dry_run:false for destructive DELETE actions."
      },
      "dry_run": {
        "type": "boolean",
        "description": "Writes default to dry-run. Pass false to execute after reviewing the request preview."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Optional compact result projection. Errors and partial failures are always preserved."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 10000,
        "description": "Optional maximum list items returned after projection."
      },
      "compact": {
        "type": "boolean",
        "description": "Return compact projected results while preserving failures and pagination metadata."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": true,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
